import unittest
from banner import replace_tag

class Banner(unittest.TestCase):
    def test_literals(self):
        self.assertEqual(replace_tag('a.b axb a.b', 'a.b', 'X'), 'X axb X')
        self.assertEqual(replace_tag('[user] user', '[user]', 'Li'), 'Li user')
        self.assertEqual(replace_tag('xx|xx', 'xx', r'\1\folder'), r'\1\folder|\1\folder')
        self.assertEqual(replace_tag('aaaaa', 'aa', 'z'), 'zza')
        self.assertEqual(replace_tag('plain', 'absent', ''), 'plain')
    def test_empty_tag(self):
        with self.assertRaises(ValueError): replace_tag('abc', '', 'x')

if __name__ == '__main__':
    unittest.main()

